sys_script_client.script:
function onSubmit() {

    var isValid = true;

    // 1. Patient
    if (g_form.getValue('patient') == '') {
        g_form.addErrorMessage('Patient is required.');
        isValid = false;
    }

    // 2. Admission
    if (g_form.getValue('admission') == '') {
        g_form.addErrorMessage('Admission is required.');
        isValid = false;
    }

    // 3. Care Plan
    if (g_form.getValue('care_plan') == '') {
        g_form.addErrorMessage('Care Plan is required.');
        isValid = false;
    }

    // 4. Milestone Name
    if (g_form.getValue('milestone_name').trim() == '') {
        g_form.addErrorMessage('Milestone Name is required.');
        isValid = false;
    }

    // 5. Milestone Type
    if (g_form.getValue('milestone_type') == '') {
        g_form.addErrorMessage('Milestone Type must be selected.');
        isValid = false;
    }

    // 6. Target Date
    if (g_form.getValue('target_date') == '') {
        g_form.addErrorMessage('Target Date is required.');
        isValid = false;
    }

    // 7. Completed status requires Completion Date
    if (g_form.getValue('milestone_status') == 'Completed' &&
        g_form.getValue('completion_date') == '') {

        g_form.addErrorMessage(
            'Completion Date is required when Milestone Status is Completed.'
        );

        isValid = false;
    }

    // 8. Completion Date should only be entered for Completed status
    if (g_form.getValue('completion_date') != '' &&
        g_form.getValue('milestone_status') != 'Completed') {

        g_form.addErrorMessage(
            'Completion Date can only be entered when Milestone Status is Completed.'
        );

        isValid = false;
    }

    // Stop the record from being submitted when validation fails
    if (!isValid) {
        return false;
    }

    return true;
}
